import {referenceMarkup} from './routine-ui.js';
import {focusProgress} from './fitness.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function focusMarkup(session,{data={sessions:[]},excludeId}={}){
  const p=focusProgress(session),next=p.next,e=next?.exercise,s=next?.set,circ=2*Math.PI*78;
  return `<header class="dialog-header focus-header"><button class="focus-back" data-action="focus-off">‹ 完整编辑</button><span>训练专注</span><button class="icon-button" data-action="close-editor" aria-label="关闭训练">×</button></header><div class="dialog-body focus-body"><p class="focus-session">${esc(session.title)}</p><div class="focus-rings"><svg viewBox="0 0 200 200" aria-hidden="true"><circle class="focus-track" cx="100" cy="100" r="78"/><circle class="focus-completion" cx="100" cy="100" r="78" stroke-dasharray="${circ}" stroke-dashoffset="${circ*(1-p.ratio)}"/><circle class="focus-rest-track" cx="100" cy="100" r="61"/><circle id="focus-rest-ring" cx="100" cy="100" r="61" stroke-dasharray="${2*Math.PI*61}" stroke-dashoffset="${2*Math.PI*61}"/></svg><div class="focus-ring-label"><strong>${p.done}<span>/${p.total}</span></strong><small>已完成 / 当前草稿组数</small></div></div><div class="focus-timer" role="timer"><span>休息倒计时</span><strong id="focus-rest-time">—</strong><div><button class="focus-text" data-action="skip-rest">结束休息</button><button class="focus-text" data-action="restart-rest">重新计时</button></div></div>${next?`<section class="focus-next"><span>下一组 · ${s.type==='warmup'?'热身组':'工作组'} ${next.index+1}</span><h2>${esc(e.name)}</h2>${e.setup?.equipment?`<p>${esc(e.setup.equipment)} ${esc(e.setup.seat)} ${esc(e.setup.grip)}</p>`:''}${referenceMarkup(data,e,session.date,excludeId,true)}<div class="set-row focus-row" data-set="${esc(s.id)}">${e.tracking==='reps'?'':`<label>重量 kg<input data-field="weight" aria-label="${esc(e.name)} 第${next.index+1}组重量" type="number" min="0" max="1500" step="0.5" inputmode="decimal" value="${esc(s.weight)}"></label>`}<label>次数<input data-field="reps" aria-label="${esc(e.name)} 第${next.index+1}组次数" type="number" min="1" max="100" step="1" inputmode="numeric" value="${esc(s.reps)}"></label><label>RIR<input data-field="rir" aria-label="${esc(e.name)} 第${next.index+1}组 RIR" type="number" min="0" max="10" step="0.5" inputmode="decimal" placeholder="未知" value="${esc(s.rir)}"></label><button class="done-button focus-done" data-action="toggle-set" data-id="${esc(s.id)}" aria-label="完成 ${esc(e.name)} 第${next.index+1}组" aria-pressed="false">✓ 完成这一组</button></div></section>`:`<section class="focus-next"><h2>${p.total?'当前草稿组已完成':'先加入训练动作'}</h2><p>${p.total?'可返回完整编辑补充动作，或保存实际完成的训练。':'返回完整编辑选择动作，环形进度会按当前草稿更新。'}</p><button class="secondary" data-action="focus-off">返回完整编辑</button></section>`}<p class="focus-note">环形进度来自当前训练组数；内环显示所设休息时长的已过比例。无需手表，不读取心率或热量。页面关闭后无锁屏提醒。</p><div class="validation" role="alert" id="editor-error"></div></div><footer class="dialog-footer focus-footer"><button class="primary" data-action="finish">保存已完成训练</button></footer>`;
}
